primaryQuery:
run: order_items -> {
  aggregate:
    sales_2021 is sale_price.sum() { where: year(created_at) = 2021 }
    sales_2022 is sale_price.sum() { where: year(created_at) = 2022 }
    ytd_2021_to_nov14 is sale_price.sum() { where: created_at >= @2021-01-01 and created_at < @2021-11-15 }
    window_end is max(created_at)::date
} -> {
  select:
    sales_2021
    sales_2022
    ytd_2021_to_nov14
    window_end
    naive_yoy is round(sales_2022 / sales_2021 - 1, 4)
    comparable_yoy is round(sales_2022 / ytd_2021_to_nov14 - 1, 4)
}

verifyQuery:
run: order_items -> {
  group_by: yr is year(created_at)
  aggregate:
    sales is sale_price.sum()
    to_nov14 is sale_price.sum() { where: created_at < @2021-11-15 }
    last_at is max(created_at)
} -> {
  aggregate:
    sales_2021 is sales.sum() { where: yr = 2021 }
    sales_2022 is sales.sum() { where: yr = 2022 }
    ytd_2021_to_nov14 is to_nov14.sum() { where: yr = 2021 }
    window_end is max(last_at)::date
} -> {
  select:
    sales_2021
    sales_2022
    ytd_2021_to_nov14
    window_end
    naive_yoy is round(sales_2022 / sales_2021 - 1, 4)
    comparable_yoy is round(sales_2022 / ytd_2021_to_nov14 - 1, 4)
}
